// loads per-node device json generated by gen_devices.sh.
// uses vite's import.meta.glob so any *.json dropped in this dir is auto-discovered,
// no code change needed when you add a node.

const modules = import.meta.glob('./*.json', { eager: true });

// flatten into a list of { host, index, name, cc, ...limits } entries
export function loadDevices() {
  const out = [];
  for (const path in modules) {
    const data = modules[path].default ?? modules[path];
    const host = data.host ?? path.replace('./', '').replace('.json', '');
    for (const dev of data.devices ?? []) {
      out.push({ host, ...dev });
    }
  }
  return out;
}

// stable label for a device in a picker
export function deviceLabel(d) {
  return `${d.host} · gpu ${d.index} · ${d.name} (cc ${d.cc})`;
}
